# Every fact here comes from a named source, listed at the end of each guide. No hotel names, no invented prices, no em dashes.
# "id" = Indonesian written natively (not machine translated); the other languages are machine translated at build time.
from guides4 import PL, GD, MAP, _km, _drive, TMC, WGP

def SRC(*links): return "<h2>Sources</h2><ul class=\"src\">" + "".join(f'<li><a href="{u}" rel="noopener nofollow" target="_blank">{t}</a></li>' for t, u in links) + "</ul>"
def SRC_ID(*links): return SRC(*links).replace("<h2>Sources</h2>", "<h2>Sumber</h2>")
def G(s, img, t, d, b, faq, idn=None): g = {"s": s, "img": img, "t": t, "d": d, "b": b, "faq": faq}; g.update({"id_native": idn} if idn else {}); return g

